BAD = "def add(a, b):\n    return a - b"

def style(code):
    return all(len(l) <= 40 for l in code.splitlines())

def tests(code):
    scope = {}
    exec(code, scope)
    return scope["add"](2, 3) == 5

def build(code):
    compile(code, "app.py", "exec")
    return True

def run_ci(code):
    report = []
    for step in (style, tests, build):
        ok = step(code)
        report.append({"step": step.__name__, "result": "pass" if ok else "FAIL"})
        if not ok:
            return report, "BLOCKED"
    return report, "MERGED"

for label, change in [("good change", GOOD), ("broken change", BAD)]:
    report, verdict = run_ci(change)
    show(report, label)
    print(label, "->", verdict)

