import itertools

class Main:
    def __init__(self, copies):
        self.data = {}
        self.copies = [{} for _ in range(copies)]
    def write(self, key, value):
        self.data[key] = value
        for c in self.copies:
            c[key] = value

class Cluster:
    def __init__(self, shards):
        self.shards = [Main(2) for _ in range(shards)]
        self.turn = itertools.cycle(range(2))
    def pick(self, user_id):
        return self.shards[user_id % len(self.shards)]
    def save(self, user_id, name):
        self.pick(user_id).write(user_id, name)
    def read(self, user_id):
        shard = self.pick(user_id)
        copy = shard.copies[next(self.turn)]
        return copy.get(user_id)

db = Cluster(3)
names = ["Ana", "Bo", "Cy", "Di", "Eli", "Flo", "Gus"]
for i, n in enumerate(names):
    db.save(i, n)
print("user 4 is", db.read(4))
show([len(s.data) for s in db.shards], "users per shard")
show({i: sorted(s.data.values()) for i, s in enumerate(db.shards)}, "who lives where")

