    tool, arg = pretend_model(seen)
    if tool == "done":
        print("ANSWER:", arg)
        break
    result = TOOLS[tool](arg)
    seen.append({"tool": tool, "arg": arg, "result": result})
    print(turn, tool, arg, "->", result)
